changeSet.sql:
CREATE TABLE model_calibrations ( id BIGSERIAL PRIMARY KEY, model_name TEXT NOT NULL, calibration_key_hash TEXT, calibration_key JSONB, backend TEXT, gpu_name TEXT, vllm_version TEXT, tensor_parallel_size INTEGER, profile JSONB NOT NULL, source_provider_id INTEGER REFERENCES providers(id) ON DELETE SET NULL, calibrated_at TIMESTAMPTZ NOT NULL, confirmations INTEGER NOT NULL DEFAULT 0, divergences INTEGER NOT NULL DEFAULT 0, adoptions INTEGER NOT NULL DEFAULT 0, invalidated_at TIMESTAMPTZ, invalidation_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE INDEX idx_model_calibrations_lookup ON model_calibrations (model_name, calibration_key_hash, calibrated_at DESC) WHERE invalidated_at IS NULL;
CREATE UNIQUE INDEX uq_model_calibrations_source_run ON model_calibrations (model_name, source_provider_id, calibrated_at);
